 * ascending name order, walking each task's dependencies in ascending name
 * order. Throws a `CliError` for the first cycle such a search re-enters,
 * reporting the path from the re-entered task through the search stack and
 * back to it.
 */
export function detectCycle(costs, deps) {
  const state = new Map()
  const stack = []

  const visit = (name) => {
    state.set(name, 'visiting')
    stack.push(name)
    const targets = [...deps.get(name)].sort()
    for (const target of targets) {
      const targetState = state.get(target)
      if (targetState === 'visiting') {
        const start = stack.indexOf(target)
        const cycle = stack.slice(start).concat(target)
        throw new CliError(3, `cycle: ${cycle.join(' -> ')}`)
      }
      if (targetState !== 'done') {
        visit(target)
      }
    }
    state.set(name, 'done')
    stack.pop()
  }

  for (const name of [...costs.keys()].sort()) {
    if (!state.has(name)) visit(name)
  }
}

/**
 * Computes, for every task, its start time, finish time and depth (the wave
 * it sits in). A task with no dependencies starts at 0 and sits in wave 0;
 * otherwise its start is the greatest finish among its dependencies and its
 * depth is one past the greatest depth among them. Assumes the graph has
 * already been checked for cycles.
 */
export function computeTimes(costs, deps) {
  const start = new Map()
  const finish = new Map()
  const depth = new Map()

  const compute = (name) => {
    if (finish.has(name)) return
    const targets = deps.get(name)
    let taskStart = 0
    let taskDepth = 0
    for (const target of targets) {
      compute(target)
      if (finish.get(target) > taskStart) taskStart = finish.get(target)
      if (depth.get(target) + 1 > taskDepth) taskDepth = depth.get(target) + 1
    }
    start.set(name, taskStart)
    depth.set(name, taskDepth)
    finish.set(name, taskStart + costs.get(name))
  }

  for (const name of costs.keys()) compute(name)

  return { start, finish, depth }
}

/**
 * Computes, for every task, the cost of the longest chain that begins at it:
 * its own cost plus the costs down to any task that nothing depends on.
 * Assumes the graph has already been checked for cycles.
 */
export function computePriorities(costs, deps) {
  const dependents = new Map()
  for (const name of costs.keys()) dependents.set(name, [])
  for (const [name, targets] of deps) {
    for (const target of targets) dependents.get(target).push(name)
  }

  const priority = new Map()
  const compute = (name) => {
    if (priority.has(name)) return priority.get(name)
    let best = 0
    for (const dependent of dependents.get(name)) {
      const value = compute(dependent)
      if (value > best) best = value
    }
    const result = costs.get(name) + best
    priority.set(name, result)
    return result
  }

  for (const name of costs.keys()) compute(name)
  return priority
}

/**
 * Simulates the graph on `workerCount` workers, always starting the ready
 * task of greatest priority (ties broken by ascending name) on the free
 * worker of smallest index, and advancing time to the next worker-free
 * instant when nothing more can start. Assumes the graph has already been
 * checked for cycles.
 */
export function simulatePack(costs, deps, workerCount) {
  const priorities = computePriorities(costs, deps)
  const busyUntil = new Array(workerCount).fill(0)
  const runs = Array.from({ length: workerCount }, () => [])
  const finishTime = new Map()
  const remaining = new Set(costs.keys())

  let currentTime = 0

  const isReady = (name) => {
    for (const dependency of deps.get(name)) {
      if (!finishTime.has(dependency) || finishTime.get(dependency) > currentTime) {
        return false
      }
    }
    return true
  }

  while (remaining.size > 0) {
    let started = true
    while (started) {
      started = false

      let worker = -1
      for (let i = 0; i < workerCount; i++) {
        if (busyUntil[i] <= currentTime) {
          worker = i
          break
        }
      }
      if (worker === -1) break

      let chosen = null
      for (const name of remaining) {
        if (!isReady(name)) continue
        if (
          chosen === null ||
          priorities.get(name) > priorities.get(chosen) ||
          (priorities.get(name) === priorities.get(chosen) && name < chosen)
        ) {
          chosen = name
        }
      }
      if (chosen === null) break

      const taskFinish = currentTime + costs.get(chosen)
      runs[worker].push({ name: chosen, start: currentTime, finish: taskFinish })
      busyUntil[worker] = taskFinish
      finishTime.set(chosen, taskFinish)
      remaining.delete(chosen)
      started = true
    }

    if (remaining.size === 0) break

    let next = Infinity
    for (const time of busyUntil) {
      if (time > currentTime && time < next) next = time
    }
    currentTime = next
  }

  let makespan = 0
  for (const time of finishTime.values()) {
    if (time > makespan) makespan = time
  }

  return { runs, makespan }
}
