  }
  throw new CliError(2, USAGE)
}

function readStdin(stream) {
  return new Promise((resolve, reject) => {
    const chunks = []
    stream.on('data', (chunk) => chunks.push(chunk))
    stream.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    stream.on('error', reject)
  })
}

function runWaves(costs, deps) {
  const { finish, depth } = computeTimes(costs, deps)
  const waves = []
  for (const [name, taskDepth] of depth) {
    if (!waves[taskDepth]) waves[taskDepth] = []
    waves[taskDepth].push(name)
  }

  const lines = []
  for (let i = 0; i < waves.length; i++) {
    lines.push(`wave ${i}: ${waves[i].sort().join(' ')}`)
  }
  let total = 0
  for (const time of finish.values()) {
    if (time > total) total = time
  }
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

function runExplain(costs, deps) {
  const { start, finish, depth } = computeTimes(costs, deps)
  const lines = []
  for (const name of [...costs.keys()].sort()) {
    lines.push(`${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}`)
  }
  let total = 0
  for (const time of finish.values()) {
    if (time > total) total = time
  }
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

function runPack(costs, deps, workerCount) {
  const { runs, makespan } = simulatePack(costs, deps, workerCount)
  const lines = runs.map((run, i) => {
    const parts = run.map((task) => ` ${task.name}@${task.start}-${task.finish}`).join('')
    return `worker ${i}:${parts}`
  })
  lines.push(`makespan ${makespan}`)
  return lines.join('\n') + '\n'
}

async function main() {
  const args = parseArgs(process.argv.slice(2))
  const input = await readStdin(process.stdin)
  const { costs, deps } = parseGraph(input)
  detectCycle(costs, deps)

  let output
  if (args.mode === 'waves') {
    output = runWaves(costs, deps)
  } else if (args.mode === 'explain') {
    output = runExplain(costs, deps)
  } else {
    output = runPack(costs, deps, args.workers)
  }
  process.stdout.write(output)
}

main().catch((error) => {
  if (error instanceof CliError) {
    process.stderr.write(`error: ${error.message}\n`)
    process.exit(error.code)
  }
  throw error
})
